const listLifeChatTurnMaterials = `-- name: ListLifeChatTurnMaterials :many
WITH target AS (
    SELECT material.occurred_at
    FROM life_material material
    WHERE material.workspace_id = $1 AND material.user_id = $2
      AND material.source_type = 'chat_message' AND material.source_key = $4::text
), previous_reply AS (
    SELECT max(material.occurred_at) AS occurred_at
    FROM life_material material, target
    WHERE material.workspace_id = $1 AND material.user_id = $2
      AND material.source_type = 'chat_message'
      AND material.metadata->>'chat_session_id' = $3::text
      AND material.metadata->>'role' = 'assistant'
      AND material.occurred_at < target.occurred_at
)
SELECT material.id, material.workspace_id, material.user_id, material.source_type, material.source_key, material.source_revision, material.content, material.metadata, material.occurred_at, material.ingested_at
FROM life_material material, target, previous_reply
WHERE material.workspace_id = $1 AND material.user_id = $2
  AND material.source_type = 'chat_message'
  AND material.metadata->>'chat_session_id' = $3::text
  AND material.occurred_at > COALESCE(previous_reply.occurred_at, '-infinity'::timestamptz)
  AND material.occurred_at <= target.occurred_at
ORDER BY material.occurred_at, material.id
`

type ListLifeChatTurnMaterialsParams struct {
	WorkspaceID      pgtype.UUID `json:"workspace_id"`
	UserID           pgtype.UUID `json:"user_id"`
	ChatSessionID    string      `json:"chat_session_id"`
	ThroughMessageID string      `json:"through_message_id"`
}

