const scrubLifeCognitionTasksByMaterialIDs = `-- name: ScrubLifeCognitionTasksByMaterialIDs :exec
WITH queued_batches AS MATERIALIZED (
    SELECT job.id,
           (SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
              FROM jsonb_array_elements_text(
                  COALESCE(job.input->'material_ids', jsonb_build_array(job.input->>'material_id'))
              ) material_id(value)
             WHERE value <> ALL($3::text[])) AS remaining_material_ids,
           (SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
              FROM jsonb_array_elements_text(COALESCE(job.input->'processing_cursors', '[]'::jsonb)) cursor(value)
             WHERE replace(value, 'material:', '') <> ALL($3::text[])) AS remaining_cursors
      FROM life_cognition_job job
     WHERE job.workspace_id = $1 AND job.user_id = $2
       AND job.task_id IS NULL AND job.status IN ('queued', 'failed')
       AND (job.input->>'material_id' = ANY($3::text[]) OR EXISTS (
           SELECT 1
             FROM jsonb_array_elements_text(COALESCE(job.input->'material_ids', '[]'::jsonb)) material_id(value)
            WHERE value = ANY($3::text[])
       ))
), update_nonempty_batches AS (
    UPDATE life_cognition_job job
       SET input = jsonb_set(
               jsonb_set(job.input - 'material_id', '{material_ids}', batch.remaining_material_ids),
               '{processing_cursors}', batch.remaining_cursors
           ),
           updated_at = now()
      FROM queued_batches batch
     WHERE job.id = batch.id AND jsonb_array_length(batch.remaining_material_ids) > 0
), delete_empty_batches AS (
    DELETE FROM life_cognition_job job
     USING queued_batches batch
     WHERE job.id = batch.id AND jsonb_array_length(batch.remaining_material_ids) = 0
), affected_tasks AS MATERIALIZED (
    SELECT DISTINCT task.id
    FROM agent_task_queue task
    JOIN life_cognition_job job ON job.task_id = task.id
    WHERE job.workspace_id = $1 AND job.user_id = $2
      AND (EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
              COALESCE(task.context->'input'->'new_materials', '[]'::jsonb)
              || COALESCE(task.context->'input'->'material_index', '[]'::jsonb)
          ) material
          WHERE material->>'id' = ANY($3::text[])
      ) OR EXISTS (
          SELECT 1
          FROM jsonb_array_elements(COALESCE(task.context->'input'->'period_chronicles', '[]'::jsonb)) chronicle,
               jsonb_array_elements(COALESCE(chronicle->'evidence', '[]'::jsonb)) evidence
          WHERE evidence->>'source_id' = ANY($3::text[])
      ))
), scrubbed_jobs AS (
    UPDATE life_cognition_job job
    SET input = '{}'::jsonb,
        output = NULL,
        status = CASE WHEN job.status IN ('queued', 'running', 'failed') THEN 'cancelled' ELSE job.status END,
        error = CASE WHEN job.status IN ('queued', 'running', 'failed') THEN 'source permanently forgotten' ELSE '' END,
        updated_at = now()
    WHERE job.task_id IN (SELECT id FROM affected_tasks)
    RETURNING job.task_id
)
UPDATE agent_task_queue task
SET context = jsonb_build_object('type', 'life_cognition', 'source_forgotten', true),
    result = NULL,
    status = CASE WHEN task.status IN ('queued', 'dispatched', 'running') THEN 'cancelled' ELSE task.status END,
    error = CASE WHEN task.status IN ('queued', 'dispatched', 'running') THEN 'source permanently forgotten' ELSE NULL END,
    completed_at = CASE WHEN task.status IN ('queued', 'dispatched', 'running') THEN now() ELSE task.completed_at END,
    session_id = NULL,
    work_dir = NULL,
    trigger_summary = '人生后台任务（来源已永久删除）'
WHERE task.id IN (SELECT id FROM affected_tasks)
`

type ScrubLifeCognitionTasksByMaterialIDsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UserID      pgtype.UUID `json:"user_id"`
	Column3     []string    `json:"column_3"`
}

func (q *Queries) ScrubLifeCognitionTasksByMaterialIDs(ctx context.Context, arg ScrubLifeCognitionTasksByMaterialIDsParams) error {
	_, err := q.db.Exec(ctx, scrubLifeCognitionTasksByMaterialIDs, arg.WorkspaceID, arg.UserID, arg.Column3)
	return err
}

const scrubLifeCognitionTasksByMemoryIDs = `-- name: ScrubLifeCognitionTasksByMemoryIDs :exec
WITH RECURSIVE documents AS (
    SELECT id AS job_id, input AS value
    FROM life_cognition_job
    WHERE life_cognition_job.workspace_id = $1 AND life_cognition_job.user_id = $2
    UNION ALL
    SELECT id AS job_id, output AS value
    FROM life_cognition_job
    WHERE life_cognition_job.workspace_id = $1 AND life_cognition_job.user_id = $2
      AND output IS NOT NULL
), json_values AS (
    SELECT job_id, value FROM documents
    UNION ALL
    SELECT parent.job_id, child.value
    FROM json_values parent
    CROSS JOIN LATERAL (
        SELECT object_value.value
        FROM jsonb_each(
            CASE WHEN jsonb_typeof(parent.value) = 'object'
                 THEN parent.value ELSE '{}'::jsonb END
        ) AS object_value(key, value)
        UNION ALL
        SELECT array_value.value
        FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(parent.value) = 'array'
                 THEN parent.value ELSE '[]'::jsonb END
        ) AS array_value(value)
    ) child
), affected_jobs AS MATERIALIZED (
    SELECT DISTINCT job_id
    FROM json_values
    WHERE value #>> '{}' = ANY($3::text[])
       OR value #>> '{}' = ANY(
            SELECT 'memory:' || memory_id
            FROM unnest($3::text[]) AS memory_ids(memory_id)
       )
), affected_tasks AS MATERIALIZED (
    SELECT DISTINCT task.id
    FROM agent_task_queue task
    JOIN life_cognition_job job ON job.task_id = task.id
    WHERE job.id IN (SELECT job_id FROM affected_jobs)
), scrubbed_jobs AS (
    UPDATE life_cognition_job job
    SET input = '{}'::jsonb,
        output = NULL,
        source_ids = '[]'::jsonb,
        output_summary = NULL,
        claim_token = NULL,
        lease_until = NULL,
        status = CASE WHEN job.status <> 'cancelled' THEN 'cancelled' ELSE job.status END,
        error = 'source permanently forgotten',
        completed_at = COALESCE(job.completed_at, now()),
        updated_at = now()
    WHERE job.id IN (SELECT job_id FROM affected_jobs)
    RETURNING job.task_id
)
UPDATE agent_task_queue task
SET context = jsonb_build_object('type', 'life_cognition', 'source_forgotten', true),
    result = NULL,
    status = CASE WHEN task.status <> 'cancelled' THEN 'cancelled' ELSE task.status END,
    error = 'source permanently forgotten',
    completed_at = COALESCE(task.completed_at, now()),
    session_id = NULL,
    work_dir = NULL,
    trigger_summary = '人生后台任务（来源已永久删除）'
WHERE task.id IN (SELECT id FROM affected_tasks)
`

type ScrubLifeCognitionTasksByMemoryIDsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UserID      pgtype.UUID `json:"user_id"`
	Column3     []string    `json:"column_3"`
}

// Memory deletion must fence every cognition copy, including a job that has
// already been claimed and a completed job whose output still contains the
// deleted memory. Walk the structured JSON documents instead of relying on a
// particular job type or field name; source ids may appear in nested evidence,
// context snapshots, or observer inputs.
func (q *Queries) ScrubLifeCognitionTasksByMemoryIDs(ctx context.Context, arg ScrubLifeCognitionTasksByMemoryIDsParams) error {
	_, err := q.db.Exec(ctx, scrubLifeCognitionTasksByMemoryIDs, arg.WorkspaceID, arg.UserID, arg.Column3)
	return err
}

